# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">GELENEKSEL TARİHÇİLİKTEN DİJİTAL TARİHÇİLİĞE DÖNÜŞÜM</text>\n  <rect x="25" y="42" width="315" height="200" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e40af">DİJİTALLEŞME ÖNCESİ (GELENEKSEL)</text>\n  <text x="40" y="92" font-size="11.5" fill="#1e3a8a">• Arşiv ve kütüphanelere bizzat giderek fiziksel</text>\n  <text x="48" y="108" font-size="11" fill="#1e3a8a">belge arama (uzun zaman ve yüksek ulaşım maliyeti).</text>\n  <text x="40" y="132" font-size="11.5" fill="#1e3a8a">• Belgelerin tek tek elle fişlenmesi, defterlere</text>\n  <text x="48" y="148" font-size="11" fill="#1e3a8a">not alınması ve sınırlı sayıda kaynağın taranabilmesi.</text>\n  <text x="40" y="172" font-size="11.5" fill="#1e3a8a">• Nadir yazma eserlerin ve fermanların fiziksel</text>\n  <text x="48" y="188" font-size="11" fill="#1e3a8a">temas nedeniyle yıpranma tehlikesi taşıması.</text>\n  <text x="40" y="214" font-size="11.5" font-weight="bold" fill="#1d4ed8">• Sonuçların yalnızca basılı kitap/makale olarak yayımı.</text>\n  <rect x="355" y="42" width="320" height="200" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="515" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">DİJİTAL DÖNEM (DİJİTAL TARİHÇİLİK)</text>\n  <text x="370" y="92" font-size="11.5" fill="#14532d">• Dijital arşivler, e-kütüphaneler ve çevrim içi</text>\n  <text x="378" y="108" font-size="11" fill="#14532d">veri tabanlarına dünyanın her yerinden saniyeler içinde erişim.</text>\n  <text x="370" y="132" font-size="11.5" fill="#14532d">• OCR (Optik Karakter Tanıma), HTR (El Yazısı Tanıma)</text>\n  <text x="378" y="148" font-size="11" fill="#14532d">ve Büyük Veri (Big Data) ile milyonlarca belgenin analizi.</text>\n  <text x="370" y="172" font-size="11.5" fill="#14532d">• Orijinal belgelerin yıpranmadan dijital kopyalarla korunması.</text>\n  <text x="370" y="196" font-size="11.5" font-weight="bold" fill="#15803d">• Sanal müzeler, 3B (3D) modelleme, CBS haritaları ve</text>\n  <text x="378" y="214" font-size="11.5" font-weight="bold" fill="#15803d">etkileşimli zaman çizelgeleriyle çok katmanlı sunum.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">DİJİTAL KAYNAK TÜRLERİ, BÜYÜK VERİ VE ARAŞTIRMA YÖNTEMLERİ</text>\n  <rect x="25" y="42" width="315" height="200" rx="10" fill="#fef3c7" stroke="#d97706" stroke-width="2"/>\n  <text x="182" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">1. SONRADAN DİJİTALLEŞTİRİLMİŞ</text>\n  <text x="182" y="81" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">(Digitized Sources)</text>\n  <text x="40" y="106" font-size="11" fill="#78350f">• Fiziksel ortamda üretilmiş (tablet, ferman, nüfus</text>\n  <text x="48" y="122" font-size="11" fill="#78350f">defteri, gazete, fotoğraf) kaynakların tarayıcılarla</text>\n  <text x="48" y="138" font-size="11" fill="#78350f">sayısal ortama aktarılmasıdır.</text>\n  <text x="182" y="164" text-anchor="middle" font-size="13" font-weight="bold" fill="#92400e">2. DOĞUŞTAN DİJİTAL KAYNAKLAR</text>\n  <text x="182" y="180" text-anchor="middle" font-size="11" font-weight="bold" fill="#b45309">(Born-Digital Sources)</text>\n  <text x="40" y="202" font-size="11" fill="#78350f">• Doğrudan dijital ortamda üretilen e-postalar, web</text>\n  <text x="48" y="218" font-size="11" fill="#78350f">siteleri, sosyal medya paylaşımları, dijital videolar.</text>\n  <rect x="355" y="42" width="320" height="200" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="515" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">DİJİTAL TARİHÇİLİK ARAÇLARI</text>\n  <text x="370" y="92" font-size="11.5" font-weight="bold" fill="#581c87">• Veri Tabanları &amp; Üst Veri (Metadata):</text>\n  <text x="378" y="108" font-size="11" fill="#6b21a8">Belgelerin tarih, yazar, konu etiketleriyle kataloglanması.</text>\n  <text x="370" y="132" font-size="11.5" font-weight="bold" fill="#581c87">• Büyük Veri (Big Data) ve Veri Madenciliği:</text>\n  <text x="378" y="148" font-size="11" fill="#6b21a8">Binlerce sicil ve nüfus kaydındaki örüntülerin analizi.</text>\n  <text x="370" y="172" font-size="11.5" font-weight="bold" fill="#581c87">• Tarihsel CBS (H-GIS) ve Ağ Analizi:</text>\n  <text x="378" y="188" font-size="11" fill="#6b21a8">Ticaret yollarının, göçlerin ve savaşların haritalanması.</text>\n  <text x="370" y="212" font-size="11.5" font-weight="bold" fill="#581c87">• 3B Rekonstrüksiyon &amp; Sanal Müze:</text>\n  <text x="378" y="228" font-size="11" fill="#6b21a8">Antik yapıların ve arkeolojik buluntuların modellenmesi.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">DİJİTAL TARİHÇİLİKTE FIRSATLAR, RİSKLER VE ELEŞTİREL DOĞRULAMA</text>\n  <rect x="25" y="42" width="315" height="200" rx="10" fill="#ecfeff" stroke="#0891b2" stroke-width="2"/>\n  <text x="182" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#155e75">OLUMLU KATKILAR (FIRSATLAR)</text>\n  <text x="40" y="92" font-size="11.5" fill="#164e63">• Bilginin Demokratikleşmesi: Arşivlerin ve nadir</text>\n  <text x="48" y="108" font-size="11" fill="#155e75">eserlerin tüm dünyadaki araştırmacılara açılması.</text>\n  <text x="40" y="132" font-size="11.5" fill="#164e63">• Hız ve Kapsam: Aylar sürecek tarama ve tasnif</text>\n  <text x="48" y="148" font-size="11" fill="#155e75">aşamalarının saniyeler içinde tamamlanması.</text>\n  <text x="40" y="172" font-size="11.5" fill="#164e63">• Kültürel Mirasın Korunması: Yangın, sel veya</text>\n  <text x="48" y="188" font-size="11" fill="#155e75">yıpranmaya karşı dijital yedekleme (arşivleme).</text>\n  <text x="40" y="212" font-size="11.5" font-weight="bold" fill="#0e7490">• Disiplinler Arası İş Birliği (Bilişim, Coğrafya, İstatistik).</text>\n  <rect x="355" y="42" width="320" height="200" rx="10" fill="#fff1f2" stroke="#e11d48" stroke-width="2"/>\n  <text x="515" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#9f1239">RİSKLER, TENKİT VE ARAŞTIRMA ETİĞİ</text>\n  <text x="370" y="92" font-size="11.5" font-weight="bold" fill="#881337">• Dezenformasyon ve Sahte İçerik (Deepfake):</text>\n  <text x="378" y="108" font-size="11" fill="#9f1239">Dijital ortamda manipüle edilmiş fotoğraf ve belgeler.</text>\n  <text x="370" y="130" font-size="11.5" font-weight="bold" fill="#881337">• Dijital Tenkit (Kaynak Eleştirisi):</text>\n  <text x="378" y="146" font-size="11" fill="#9f1239">Site uzantısı (.gov.tr, .edu.tr, .org), yazar kimliği ve</text>\n  <text x="378" y="162" font-size="11" fill="#9f1239">birincil arşiv belgeleriyle çapraz doğrulama şarttır.</text>\n  <text x="370" y="184" font-size="11.5" font-weight="bold" fill="#881337">• Dijital Unutulma / Veri Kaybı &amp; Etik:</text>\n  <text x="378" y="200" font-size="11" fill="#9f1239">Format eskimesi riski; ayrıca intihalden (aşırmacılık) kaçınma,</text>\n  <text x="378" y="216" font-size="11" fill="#9f1239">telif haklarına ve kişisel mahremiyete saygı zorunludur.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get('bolumler', [])):
        if i < len(SVGS):
            b['gorsel'] = SVGS[i]
